dashboard.definition:
{
	"title": "Segmentation Overview",
	"description": "Summarize segment health, policy alignment, and areas needing investigation.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Scalable Network Segmentation",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/segmentation.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Segmentation Overview\nSummarize segment health, policy alignment, and areas needing investigation."
			}
		},
		"viz_secure_networking_sgt_by_site": {
			"type": "splunk.table",
			"title": "SGT by Site",
			"dataSources": {
				"primary": "ds_secure_networking_sgt_by_site"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Breaks down Security Group Tag–tagged ISE authentication events by site location , using ISE's own structured Location hierarchy — a real, validated \"SGT by Site\" view for the Segmentation pillar."
		},
		"viz_secure_networking_ip_sgt_bindings_by_group": {
			"type": "splunk.table",
			"title": "IP-SGT Bindings by Security Group",
			"dataSources": {
				"primary": "ds_secure_networking_ip_sgt_bindings_by_group"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Shows the distribution of IP-to-SGT bindings across Security Group Tags, reporting how many bound IPs fall under each Security Group — the core \"SGT by Site/Device\" view for the Segmentation pillar."
		},
		"viz_secure_networking_sgt_distribution_by_site_device": {
			"type": "splunk.table",
			"title": "SGT Distribution by Site and Device",
			"dataSources": {
				"primary": "ds_secure_networking_sgt_distribution_by_site_device"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Breaks SGT-tagged authentications down by site, network device, and Security Group Tag for segmentation drilldowns."
		},
		"viz_secure_networking_sgt_binding_inventory": {
			"type": "splunk.table",
			"title": "SGT Binding Inventory",
			"dataSources": {
				"primary": "ds_secure_networking_sgt_binding_inventory"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Summarizes ISE IP-SGT binding inventory by Security Group Tag, binding type, SXP domain, source node, peer path, and bound prefixes."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Network security and segmentation owners  •  **Sources:** Cisco ISE Security Group Tag and IP-SGT binding telemetry  •  **Reading guide:** Start with binding distribution, then use site and device detail to locate gaps.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Binding inventory\nStart with binding distribution, then use site and device detail to locate gaps."
			}
		}
	},
	"dataSources": {
		"ds_secure_networking_sgt_by_site": {
			"name": "Secure Networking - SGT by Site",
			"options": {
				"ref": "secure_networking_sgt_by_site",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_ip_sgt_bindings_by_group": {
			"name": "Secure Networking - IP-SGT Bindings by Security Group",
			"options": {
				"ref": "secure_networking_ip_sgt_bindings_by_group",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_sgt_distribution_by_site_device": {
			"name": "Secure Networking - SGT Distribution by Site and Device",
			"options": {
				"ref": "secure_networking_sgt_distribution_by_site_device",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_sgt_binding_inventory": {
			"name": "Secure Networking - SGT Binding Inventory",
			"options": {
				"ref": "secure_networking_sgt_binding_inventory",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 878,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_sgt_by_site",
						"position": {
							"x": 20,
							"y": 242,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_ip_sgt_bindings_by_group",
						"position": {
							"x": 730,
							"y": 242,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_sgt_distribution_by_site_device",
						"position": {
							"x": 20,
							"y": 558,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_sgt_binding_inventory",
						"position": {
							"x": 730,
							"y": 558,
							"w": 690,
							"h": 300
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
